  FT["PH-H10247"] = {"id":"PH-H10247","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11819_2022.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Initao市","en":"An Act Converting the Satellite Office of the Land Transportation Office (LTO) Located in the Municipality of Initao, Province of Misamis Oriental Into a Regular LTO District Office and Appropriating Funds Therefor","orig":"An Act Converting the Satellite Office of the Land Transportation Office (LTO) Located in the Municipality of Initao, Province of Misamis Oriental Into a Regular LTO District Office and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11819","issuingBody":"Congress of the Philippines","promulgatedDate":"2022-06-02","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2022/ra_11819_2022.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10247-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Satellite Office of the Land Transportation Office (LTO) in the Municipality of Initao, Province of Misamis Oriental is hereby converted into a regular LTO district office to be known as the LTO District Office of Initao, Misamis Oriental."}},{"id":"PH-H10247-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Transportation shall immediately include in the Department's program the operationalization of a regular LTO district office in the Municipality of Initao, Province of Misamis Oriental, the initial funding of which shall be charged against the current year's appropriations of the Initao LTO Satellite Office located in the Municipality of Initao, Province of Misamis Oriental. Thereafter, such sums as may be necessary for the continued operation of the regular LTO district office shall be included in the annual General Appropriations Act."}},{"id":"PH-H10247-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Within ninety (90) days from the effectivity of this Act, the Secretary of Transportation shall promulgate the rules and regulations necessary for its effective implementation."}},{"id":"PH-H10247-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p146"};
  FT["PH-H10248"] = {"id":"PH-H10248","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11820_2022.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Guimbal市","en":"An Act Converting the Guimbal, Iloilo Extension Office of the Land Transportation Office (LTO) Into a Regular LTO Class \"d\" District Office to Be Located in the Municipality of Guimbal, Province of Iloilo","orig":"An Act Converting the Guimbal, Iloilo Extension Office of the Land Transportation Office (LTO) Into a Regular LTO Class \"d\" District Office to Be Located in the Municipality of Guimbal, Province of Iloilo"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11820","issuingBody":"Congress of the Philippines","promulgatedDate":"2022-06-02","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2022/ra_11820_2022.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10248-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Conversion. - The existing Guimbal, Iloilo Extension Office of the Land Transportation Office (LTO) is hereby converted into a regular LTO Class “D” District Office to be located in the Municipality of Guimbal, Province of Iloilo."}},{"id":"PH-H10248-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Appropriations. - The Secretary of Transportation shall immediately include in the Department's program the operationalization of LTO Class “D” District Office in the Municipality of Guimbal, Province of Iloilo, the initial funding of which shall be charged against the current year's appropriations of Guimbal, Iloilo LTO Extension Office. Thereafter, such sums as may be necessary for the continued operation of the regular LTO district office shall be included in the annual General Appropriations Act."}},{"id":"PH-H10248-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Implementing Rules and Regulations. - The Assistant Secretary of the LTO, in consultation with the Secretary of the DOTr, shall formulate immediately the necessary rules and regulations to carry out the purposes of this Act."}},{"id":"PH-H10248-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p146"};
