  FT["PH-H10256"] = {"id":"PH-H10256","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11828_2022.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将宿务省首座宿务—马克坦大桥（曼达维市卢奥克描笼涯A.C. Cortes大道至拉普拉普市帕霍描笼涯曼达维—马克坦路）命名为Serging Veloso Osmeña Jr.桥的法案","en":"An Act Naming the First Cebu-Mactan Bridge Traversing the Mactan Channel Located At A.C. Cortes Avenue in Barangay Looc, Mandaue City Up to the Mandaue-Mactan Road in Barangay Pajo, Lapu-Lapu City, Both in the Province of Cebu, as Serging Veloso Osmeña Jr. Bridge","orig":"An Act Naming the First Cebu-Mactan Bridge Traversing the Mactan Channel Located At A.C. Cortes Avenue in Barangay Looc, Mandaue City Up to the Mandaue-Mactan Road in Barangay Pajo, Lapu-Lapu City, Both in the Province of Cebu, as Serging Veloso Osmeña Jr. Bridge"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 11828","issuingBody":"Congress of the Philippines","promulgatedDate":"2022-06-02","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2022/ra_11828_2022.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10256-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The First Cebu-Mactan Bridge traversing the Mactan Channel located at A.C. Cortes Avenue in Barangay Looc, Mandaue City up to the Mandaue-Mactan Road in Barangay Pajo, Lapu-Lapu City, both in the Province of Cebu, comprising a total distance of 854 meters, is hereby renamed as Serging Veloso Osmeña Jr. Bridge."}},{"id":"PH-H10256-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Public Works and Highways shall issue the necessary rules, orders, and circulars to implement the provisions of this Act within sixty (60) days from its effectivity."}},{"id":"PH-H10256-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p146","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Naming the First Cebu-Mactan Bridge Traversing the Mactan Channel Located At A.C. Cortes Avenue in Barangay Looc, Mandaue City Up to the Mandaue-Mactan Road in Barangay Pajo, Lapu-Lapu City, Both in the Province of Cebu, as Serging Veloso Osmeña Jr. Bridge","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H10257"] = {"id":"PH-H10257","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11829_2022.html","fetchedAt":"2026-10-06","articleCount":22,"structureMode":"ARTICLE","title":{"zh":"授予 Ismo Incorporated 在菲律宾建设、安装、设立、运营和维护电信系统的特许经营权法案","en":"An Act Granting Ismo Incorporated, a Franchise to Construct, Install, Establish, Operate, and Maintain Telecommunications Systems in the Philippines","orig":"An Act Granting Ismo Incorporated, a Franchise to Construct, Install, Establish, Operate, and Maintain Telecommunications Systems in the Philippines"},"level":"law","status":"active","topics":["investment","data","company"],"docNumber":"Republic Act No. 11829","issuingBody":"Congress of the Philippines","promulgatedDate":"2022-06-02","completenessNote":"全文，共 22 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2022/ra_11829_2022.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10257-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to ISMO Incorporated, hereunder referred to as the Grantee, its successors or assignees, a franchise to construct, install, establish, operate, and maintain for commercial purposes and in the public interest, throughout the Philippines and between the Philippines and other countries and territories, wired or wireless telecommunications systems including international and local exchange carrier, international and domestic gateway facility, international and domestic submarine cable landing stations, mobile, cellular, fixed line, trunked radio, fiber optics, multi-channel multipoint distribution system, satellite transmit and receiving systems, switches, electronic telecommunications or electronic communications services in or outside the Philippines and also in outer space, and value-added services such as transmission of voice, data, images, facsimile, control signs, audio and video, information services, and all other telecommunications systems and technologies as are at present available or will be made available through technological advances or innovations in the future; or construct, establish, install, maintain, acquire, lease, operate and manage the corresponding transmitting and receiving stations, lines, cables, or systems, as are convenient or essential to efficiently carry out the purpose of this franchise.\nAs used in this Act:\nElectronic communications network refers to (a) a transmission system for conveyance by means of electrical, magnetic, or electromagnetic energy, of signals of any description; and (b) any of the following as are used by the persons providing the system and in association with it, for conveyance of the signals: (1) apparatus comprised in the system; (2) apparatus used for the switching and routing of the system; and (3) software and stored data;\nElectronic communication service refers to a service consisting in or having as it principal feature the conveyance by means of electronic communications network of signals. It includes wired, wireless, fixed, cellular or mobile, or integrated telecommunications services, including value-added services, or technologies related to such services which are at present available or made available through technological advances or innovations, and fixed and mobile stations; and Telecommunications refers to any process which enables a telecommunications entity to relay and receive voice, data, electronic messages, written or printed matter, fixed or moving pictures, words, music or visible or audible signals or control signals of any design and for any purpose by wire, radio or other electromagnetic, spectral, optical, or electronic means."}},{"id":"PH-H10257-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations or facilities of the Grantee shall be constructed and operated in a manner as will, at most, result only in the minimum interference on the wavelengths or frequencies of existing stations or other stations which may be established by law, without in any way diminishing its own privilege to use its assigned wavelengths or frequencies and the quality of transmission or reception thereon should maximize rendition of the Grantee's services and the availability thereof."}},{"id":"PH-H10257-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Authority of the National Telecommunications Commission. - The Grantee shall secure from the National Telecommunications Commission (NTC)a Certificate of Public Convenience and Necessity or the appropriate permits and licenses for the construction, installation, and operation of its telecommunications systems or facilities. In issuing the certificate, the NTC shall have the power to regulate and impose such conditions relative to the construction, operation, maintenance, or service level of the telecommunications systems or facilities. Such certificate shall state the areas covered and the date the Grantee shall commence the service. The Grantee shall not use any frequency in the radio spectrum without authorization from the NTC. The NTC, however, shall not unreasonably withhold or delay the grant of such authority, permit, or license.\nIn case of any violation of the provisions of this franchise, the NTC shall have the authority to revoke or suspend, after due process, the permits or licenses it issued pursuant to the franchise. The NTC may recommend to Congress of the Philippine the revocation of the franchise for any violation of the provisions of this franchise."}},{"id":"PH-H10257-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Excavation and Restoration Works. - For the purpose of erecting and maintaining poles or other supports for said wires or other conductors for the purpose of laying and maintaining underground wires, cables, or other conductors, it shall be lawful for the Grantee, its successors or assignees, with the prior approval of the Department of Public Works and Highways (DPWH) or the local government unit (LGU) concerned, as may be appropriate, to make excavations or lay conduits in any of the public places, roads, highways, streets, lanes, alleys, avenues, sidewalks, or bridges of the provinces, cities, or municipalities: Provided, however, That a public place, road, highway, street, lane, alley, sidewalk, or bridge disturbed, altered or changes by reason of erection of poles or other supports or the underground laying of wires, other conductors or conduits, shall be repaired and replaced in workmanlike manner by said Grantee, its successors or assignees, in accordance with the standards set by the DPWH or the LGU concerned. Should the Grantee, its successors or assignees, after ten (10)-day notice from the said authority, fail, refuse, or neglect to repair or replace any part of any public place, road, highway, street, lane, alley, avenue, sidewalk, bridge altered, changed or disturbed by the said Grantee, its successors or assignees, then the DPWH or the LGU concerned shall have the right to have the same repaired and placed in good order and condition, and charge the Grantee, its successors or assignees, at double the amount of the costs and expenses for such repair or replacement."}},{"id":"PH-H10257-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Responsibility to the Public. - The Grantee shall conform to the ethics of honest enterprise and not use its stations or facilities for obscene or indecent transmission, or for dissemination of deliberately false information, or willful misrepresentation, or assist in subversive or treasonable acts.\nThe Grantee shall operate and maintain all its stations, lines, cables, systems, and equipment for the transmission and reception of messages, signals, and pulses in a satisfactory manner at all times, and as far as economical and practicable, modify, improve, or change such stations, lines, cables, systems, and equipment to keep abreast with the advances in science and technology.\nThe Grantee shall improve and extend its services in areas not yet served, and in hazard- and typhoon-prone areas that shall be determined by the National Disaster Risk Reduction and Management Council, or its legal successor, in coordination with the NTC.\nThe Grantee shall also improve and upgrade its equipment, facilities and services, in order to ensure effective compliance with the objectives of Republic Act No. 10639 or \"The Free Mobile Disaster Alerts Act.\""}},{"id":"PH-H10257-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Rates for Services. - The charges and rates for telecommunications services of the Grantee, except the rates and charges on those that may hereafter be declared or considered as nonregulated services, whether flat rates or measured rates or variations thereof, shall be subject to the approval of the NTC or its legal successor. The rates to be charged by the Grantee shall be unbundled, separable, and distinct among the services offered and shall be determined in such a manner that regulated services do not subsidize the unregulated ones."}},{"id":"PH-H10257-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Right of the Government. - The radio spectrum is a finite resource that is part of the national patrimony, and the use thereof is a privilege conferred upon the Grantee by the State that may be withdrawn any time after due process.\nA special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster, or disturbance of peace and order: to temporarily take over and operate the stations, transmitters, facilities or equipment of the Grantee; to temporarily suspend the operation of any station, transmitter, facility, or equipment in the interest of public safety, security, and public welfare; or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the Grantee for the use of said stations, transmitters, facilities, or equipment during the period when these shall be so operated."}},{"id":"PH-H10257-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Term of Franchise. - This franchise shall be in effect for a period of twenty-five (25) years from the effectivity of this Act, unless sooner revoked or cancelled. This franchise shall be deemed ipso facto revoked in the event the Grantee fails to comply with any of the following conditions:\n(a) Commencement of operations within three (3) years from the approval of its operating permit by the NTC;\n(b) Commencement of operations within five (5) years from the effectivity of this Act; and\n(c) Continuous operation for two (2) years."}},{"id":"PH-H10257-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Bond. – The Grantee shall file a bond with the NTC, in the amount that the NTC shall determine, to guarantee compliance with and fulfillment of the conditions under which this franchise is granted. If after three (3) years from the date of approval of its permit by the NTC, the Grantee shall have fulfilled the same, the bond shall be released by the NTC."}},{"id":"PH-H10257-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Right of Interconnection. - The Grantee is hereby authorized to connect or demand connection of its telecommunications systems to other telecommunications systems installed, operated, and maintained by any other duly authorized person or entity in the Philippines for the purpose of providing extended and improved telecommunications services to the public, under the terms and conditions mutually agreed upon by the parties concerned. This right shall be subject to the review and modification of the NTC."}},{"id":"PH-H10257-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Mobile Number Portability. – The Grantee shall provide mobile number portability (MNP) and its implementing mechanisms, including the required infrastructure and processes, and shall interconnect, directly or indirectly, with the infrastructure, facilities, systems, or equipment of other telecommunications franchise grantees. It shall not install network features, functions, or capabilities that will impede the implementation of a nationwide MNP system."}},{"id":"PH-H10257-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Warranty in Favor of the National and Local Governments. - The Grantee shall hold the national, provincial, city, and municipal governments of the Philippines free from all claims, liabilities, accounts, demands, or actions arising out of accidents causing injury to persons or damage to properties, during the construction or operation of the stations, transmitters, facilities, or equipment of the Grantee."}},{"id":"PH-H10257-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Sales, Lease, Transfer, Grant of Usufruct, or Assignment of Franchise. - The Grantee shall not sell, lease, transfer, grant of usufruct of, nor assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any corporation or entity, nor shall the controlling interest of the Grantee be transferred, simultaneously or contemporaneously, to any person, firm, company, corporation, or entity without the prior approval of Congress. The Grantee shall inform the Congress, through the Office of the Speaker and Office of the Senate President, of any sale, lease, transfer, grant of usufruct, or assignment of franchise or the rights and privileges acquired thereunder, or of the merger or transfer of the controlling interest of the Grantee, within sixty (60) days after the completion of the said transaction. Failure to report to Congress such change of ownership shall render the franchise ipso facto revoked. Any person or entity to which this franchise is sold, transferred, or assigned shall be subject to the same conditions, terms, restrictions, and limitations of this Act."}},{"id":"PH-H10257-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Dispersal of Ownership. - In accordance with the constitutional provision to encourage public participation in public utilities, the Grantee shall offer to Filipino citizens at least thirty percent (30%) of its outstanding capital stocks, or a higher percentage that may hereafter be provided by law, in any securities exchange in the Philippines within five (5) years from the effectivity of this Act: Provided, That in cases where public offer of shares is not applicable, other methods of encouraging public participation by citizens and corporations operating public utilities must be implemented. Noncompliance therewith shall render the franchise ipso facto revoked."}},{"id":"PH-H10257-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Commitment to Provide and Promote the Creation of Employment Opportunities. - The Grantee shall create employment opportunities and accept on-the-job trainees in the franchise operations: Provided, That priority shall be accorded to the residents of the place where the principal office of the Grantee is located: Provided, further, That the Grantee shall comply with the applicable labor standards and allowance entitlement under existing labor laws, rules and regulations and similar issuances.\nThe employment opportunities or jobs created shall be reflected in the General Information Sheet (GIS) to be submitted to Securities and Exchange Commission (SEC) annually."}},{"id":"PH-H10257-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Reportorial Requirement. - The Grantee shall submit an annual report on its compliance with the terms and conditions of the franchise and on its operations to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate, on or before April 30 of every year during the term of its franchise.\nThe annual report shall include an update on the commencement of activities, development, operation or expansion of business; audited financial statements; latest GIS officially submitted to the SEC, if applicable; certification of the NTC on the status of its permits and operations; and an update on the dispersal of ownership undertaking, if applicable.\nThe reportorial compliance certificate issued by Congress shall required before any application for permit or certificate is accepted by the NTC."}},{"id":"PH-H10257-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Fine. - Failure of the Grantee to submit the requisite annual report to Congress shall be penalized with a fine in the amount of One million pesos (P1,000,000.00) each working day of noncompliance, the effectivity of which shall commence upon applicability with other telecommunications franchise grantees: Provided, That in the interim, the Grantee shall be liable to pay the fine of Five hundred pesos (P500.00) per working day of noncompliance to the NTC. The fine shall be collected separately from the reportorial penalties imposed by the NTC, and it shall be remitted to the Bureau of Treasury."}},{"id":"PH-H10257-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Equality Clause. - Any advantage, favor, privilege, exemption or immunity granted under existing franchises, or which may hereafter be granted for telecommunications, upon prior review and approval of Congress, shall become part of this franchise and shall be accorded immediately and unconditionally to the herein Grantee: Provided, however, That the foregoing shall neither apply to nor affect the provisions of telecommunications franchises concerning territorial covered by the franchise, the life span of the franchise, or the type of service authorized by the franchise."}},{"id":"PH-H10257-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Repealability and Nonexclusivity Clause. - This franchise shall be subject to amendment, alteration, or repeal by Congress when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H10257-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Separability Clause. - If any of the sections or provisions of this Act is held invalid, all other provisions not affected thereby shall remain valid."}},{"id":"PH-H10257-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Repealing Clause. - All laws, decrees, orders, resolutions, instructions, rules and regulations, and other issuances or parts thereof which are inconsistent with the provisions of this Act are hereby repealed, amended, or modified accordingly."}},{"id":"PH-H10257-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p146","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Ismo Incorporated, a Franchise to Construct, Install, Establish, Operate, and Maintain Telecommunications Systems in the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H10258"] = {"id":"PH-H10258","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11830_2022.html","fetchedAt":"2026-10-06","articleCount":20,"structureMode":"ARTICLE","title":{"zh":"将依第 8564 号共和国法授予 Lukban 电话公司在奎松省 Lukban 市镇建设、运营和维护本地交换网络的特许经营权再续展二十五年的法案","en":"An Act Renewing for Another Twenty-Five (25) Years the Franchise Granted to Lukban Telephone System, Inc., Under Republic Act No. 8564, Entitled \"An Act Granting the Lukban Telephone System, Inc., a Franchise to Construct, Install, Maintain, Establish and Operate Local Exchange Network in the Municipality of Lukban, Province of Quezon\"","orig":"An Act Renewing for Another Twenty-Five (25) Years the Franchise Granted to Lukban Telephone System, Inc., Under Republic Act No. 8564, Entitled \"An Act Granting the Lukban Telephone System, Inc., a Franchise to Construct, Install, Maintain, Establish and Operate Local Exchange Network in the Municipality of Lukban, Province of Quezon\""},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 11830","issuingBody":"Congress of the Philippines","promulgatedDate":"2022-06-02","completenessNote":"全文，共 20 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2022/ra_11830_2022.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10258-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to Lukban Telephone System, Inc., hereunder referred to as the Grantee, its successors or assignees, under Republic Act No. 8564, to construct, install, maintain, establish, and operate for commercial purposes and in the public interest, in the Municipality of Lukban, Quezon, wired or wireless telecommunications systems and facilities for domestic telecommunications, including local exchange network, public calling stations, pay telephone stations, or wireless local loop, using copper or fiber optics cables, switches, and satellite transmit and receive systems, and their value-added services such as transmission of voice, data, facsimile, control signs, audio and video, information services, and all other telecommunication systems and technologies as are at present available or will be made available through technological advances or innovations in the future; or construct, acquire, lease, operate or manage transmitting and receiving stations, lines, cables, or systems, as are convenient or essential to efficiently carry out the purpose of this franchise, is hereby renewed for another twenty-five (25) years."}},{"id":"PH-H10258-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations or facilities of the Grantee shall be constructed and operated in a manner as will, at most, result only in the minimum interference on the wavelengths or frequencies of existing stations or other stations which may be established by law, without in any way diminishing its own privilege to use its assigned wavelengths or frequencies and the quality of transmission or reception thereon should maximize rendition of the Grantee's services and the availability thereof."}},{"id":"PH-H10258-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Authority of the National Telecommunications Commission. - The Grantee shall secure from the National Telecommunications Commission (NTC)a Certificate of Public Convenience and Necessity or the appropriate permits and licenses for the construction, installation, and operation of its telecommunications systems or facilities. In issuing the certificate, the NTC shall have the power to regulate and impose such conditions relative to the construction, operation, maintenance, or service level of the telecommunications systems or facilities. Such certificate shall state the areas covered and the date the Grantee shall commence the service. The Grantee shall not use any frequency in the radio spectrum without authorization from the NTC. The NTC, however, shall not unreasonably withhold or delay the grant of such authority, permit, or license.\nIn case of any violation of the provisions of this franchise, the NTC shall have the authority to revoke or suspend, after due process, the permits or licenses it issued pursuant to the franchise. The NTC may recommend to Congress of the Philippine the revocation of the franchise for any violation of the provisions of this franchise."}},{"id":"PH-H10258-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Excavation and Restoration Works. - For the purpose of erecting and maintaining poles or other supports for said wires or other conductors for the purpose of laying and maintaining underground wires, cables, or other conductors, it shall be lawful for the Grantee, its successors or assignees, with the prior approval of the Department of Public Works and Highways (DPWH) or the local government unit (LGU) concerned, as may be appropriate, to make excavations or lay conduits in any of the public places, roads, highways, streets, lanes, alleys, avenues, sidewalks, or bridges of the provinces, cities, or municipalities: Provided, however, That a public place, road, highway, street, lane, alley, sidewalk, or bridge disturbed, altered or changes by reason of erection of poles or other supports or the underground laying of wires, other conductors or conduits, shall be repaired and replaced in workmanlike manner by said Grantee, its successors or assignees, in accordance with the standards set by the DPWH or the LGU concerned. Should the Grantee, its successors or assignees, after ten (10)-day notice from the said authority, fail, refuse, or neglect to repair or replace any part of any public place, road, highway, street, lane, alley, avenue, sidewalk, bridge altered, changed or disturbed by the said Grantee, its successors or assignees, then the DPWH or the LGU concerned shall have the right to have the same repaired and placed in good order and condition, and charge the Grantee, its successors or assignees, at double the amount of the costs and expenses for such repair or replacement."}},{"id":"PH-H10258-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Responsibility to the Public. - The Grantee shall conform to the ethics of honest enterprise and not use its stations or facilities for obscene or indecent transmission, or for dissemination of deliberately false information, or willful misrepresentation, or assist in subversive or treasonable acts.\nThe Grantee shall operate and maintain all its stations, lines, cables, systems, and equipment for the transmission and reception of messages, signals, and pulses in a satisfactory manner at all times, and as far as economical and practicable, modify, improve, or change such stations, lines, cables, systems, and equipment to keep abreast with the advances in science and technology.\nThe Grantee shall improve and extend its services in areas not yet served, and in hazard- and typhoon-prone areas that shall be determined by the National Disaster Risk Reduction and Management Council, or its legal successor, in coordination with the NTC.\nThe Grantee shall also improve and upgrade its equipment, facilities and services, in order to ensure effective compliance with the objectives of Republic Act No. 10639 or \"The Free Mobile Disaster Alerts Act.\""}},{"id":"PH-H10258-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Rates for Services. - The charges and rates for telecommunications services of the Grantee, except the rates and charges on those that may hereafter be declared or considered as nonregulated services, whether flat rates or measured rates or variations thereof, shall be subject to the approval of the NTC or its legal successor. The rates to be charged by the Grantee shall be unbundled, separable, and distinct among the services offered and shall be determined in such a manner that regulated services do not subsidize the unregulated ones."}},{"id":"PH-H10258-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Right of the Government. - The radio spectrum is a finite resource that is part of the national patrimony, and the use thereof is a privilege conferred upon the Grantee by the State that may be withdrawn any time after due process.\nA special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster, or disturbance of peace and order: to temporarily take over and operate the stations, transmitters, facilities or equipment of the Grantee; to temporarily suspend the operation of any station, transmitter, facility, or equipment in the interest of public safety, security, and public welfare; or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the Grantee for the use of said stations, transmitters, facilities, or equipment during the period when these shall be so operated."}},{"id":"PH-H10258-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Term of Franchise. - This franchise shall be in effect for a period of twenty-five (25) years from the effectivity of this Act, unless sooner revoked or cancelled. This franchise shall be deemed ipso facto revoked in the event the Grantee fails to operate continuously for two (2) years."}},{"id":"PH-H10258-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Right of Interconnection. - The Grantee is hereby authorized to connect or demand connection of its telecommunications systems to other telecommunications systems installed, operated, and maintained by any other duly authorized person or entity in the Philippines for the purpose of providing extended and improved telecommunications services to the public, under the terms and conditions mutually agreed upon by the parties concerned. This right shall be subject to the review and modification of the NTC."}},{"id":"PH-H10258-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of the National and Local Governments. - The Grantee shall hold the national, provincial, city, and municipal governments of the Philippines free from all claims, liabilities, accounts, demands, or actions arising out of accidents causing injury to persons or damage to properties, during the construction or operation of the stations, transmitters, facilities, or equipment of the Grantee."}},{"id":"PH-H10258-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sales, Lease, Transfer, Grant of Usufruct, or Assignment of Franchise. - The Grantee shall not sell, lease, transfer, grant of usufruct of, nor assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any corporation or entity, nor shall the controlling interest of the Grantee be transferred, simultaneously or contemporaneously, to any person, firm, company, corporation, or entity without the prior approval of Congress. The Grantee shall inform the Congress, through the Office of the Speaker and Office of the Senate President, of any sale, lease, transfer, grant of usufruct, or assignment of franchise or the rights and privileges acquired thereunder, or of the merger or transfer of the controlling interest of the Grantee, within sixty (60) days after the completion of the said transaction. Failure to report to Congress such change of ownership shall render the franchise ipso facto revoked. Any person or entity to which this franchise is sold, transferred, or assigned shall be subject to the same conditions, terms, restrictions, and limitations of this Act."}},{"id":"PH-H10258-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Dispersal of Ownership. - In accordance with the constitutional provision to encourage public participation in public utilities, the Grantee shall offer to Filipino citizens at least thirty percent (30%) of its outstanding capital stocks, or a higher percentage that may hereafter be provided by law, in any securities exchange in the Philippines within five (5) years from the effectivity of this Act: Provided, That in cases where public offer of shares is not applicable, other methods of encouraging public participation by citizens and corporations operating public utilities must be implemented. Noncompliance therewith shall render the franchise ipso facto revoked."}},{"id":"PH-H10258-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Commitment to Provide and Promote the Creation of Employment Opportunities. - The Grantee shall create employment opportunities and accept on-the-job trainees in the franchise operations: Provided, That priority shall be accorded to the residents of the place where the principal office of the Grantee is located: Provided, further, That the Grantee shall comply with the applicable labor standards and allowance entitlement under existing labor laws, rules and regulations and similar issuances.\nThe employment opportunities or jobs created shall be reflected in the General Information Sheet (GIS) to be submitted to Securities and Exchange Commission (SEC) annually."}},{"id":"PH-H10258-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Reportorial Requirement. - The Grantee shall submit an annual report on its compliance with the terms and conditions of the franchise and on its operations to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate, on or before April 30 of every year during the term of its franchise.\nThe annual report shall include an update on the commencement of activities, development, operation or expansion of business; audited financial statements; latest GIS officially submitted to the SEC, if applicable; certification of the NTC on the status of its permits and operations; and an update on the dispersal of ownership undertaking, if applicable.\nThe reportorial compliance certificate issued by Congress shall required before any application for permit or certificate is accepted by the NTC."}},{"id":"PH-H10258-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Fine. - Failure of the Grantee to submit the requisite annual report to Congress shall be penalized with a fine in the amount of One million pesos (P1,000,000.00) each working day of noncompliance, the effectivity of which shall commence upon applicability with other telecommunications franchise grantees: Provided, That in the interim, the Grantee shall be liable to pay the fine of Five hundred pesos (P500.00) per working day of noncompliance to the NTC. The fine shall be collected separately from the reportorial penalties imposed by the NTC, and it shall be remitted to the Bureau of Treasury."}},{"id":"PH-H10258-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Equality of Treatment in the Telecommunications Industry. - Any advantage, favor, privilege, exemption or immunity granted under existing franchises, or which may hereafter be granted for telecommunications, upon prior review and approval of Congress, shall become part of this franchise and shall be accorded immediately and unconditionally to the herein Grantee: Provided, however, That the foregoing shall neither apply to nor affect the provisions of telecommunications franchises concerning territorial covered by the franchise, the life span of the franchise, or the type of service authorized by the franchise."}},{"id":"PH-H10258-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Repealability and Nonexclusivity Clause. - This franchise shall be subject to amendment, alteration, or repeal by Congress when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H10258-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Separability Clause. - If any of the sections or provisions of this Act is held invalid, all other provisions not affected thereby shall remain valid."}},{"id":"PH-H10258-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Repealing Clause. - All laws, decrees, orders, resolutions, instructions, rules and regulations, and other issuances or parts thereof which are inconsistent with the provisions of this Act are hereby repealed, amended, or modified accordingly."}},{"id":"PH-H10258-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p146","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Renewing for Another Twenty-Five (25) Years the Franchise Granted to Lukban Telephone System, Inc., Under Republic Act No. 8564, Entitled \"An Act Granting the Lukban Telephone System, Inc., a Franchise to Construct, Install, Maintain, Establish and Operate Local Exchange Network in the Municipality of Lukban, Province of Quezon\"","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H10259"] = {"id":"PH-H10259","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11831_2022.html","fetchedAt":"2026-10-06","articleCount":20,"structureMode":"ARTICLE","title":{"zh":"将依第 8579 号共和国法授予 Continental 电信系统公司在八打雁、拉古纳与马斯巴特省建设、运营和维护本地交换网络的特许经营权再续展二十五年的法案","en":"An Act Renewing for Another Twenty-Five (25) Years the Franchise Granted to Continental Telecommunications System Inc., Under the Republic Act No. 8579, Entitled \"an Act Granting the Continental Telecommunications System, Inc., a Franchise to Construct, Install, Maintain, Establish and Operate Local Exchange Network in the Provinces of Batangas, Laguna, and Masbate\"","orig":"An Act Renewing for Another Twenty-Five (25) Years the Franchise Granted to Continental Telecommunications System Inc., Under the Republic Act No. 8579, Entitled \"an Act Granting the Continental Telecommunications System, Inc., a Franchise to Construct, Install, Maintain, Establish and Operate Local Exchange Network in the Provinces of Batangas, Laguna, and Masbate\""},"level":"law","status":"active","topics":["investment","data"],"docNumber":"Republic Act No. 11831","issuingBody":"Congress of the Philippines","promulgatedDate":"2022-06-02","completenessNote":"全文，共 20 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2022/ra_11831_2022.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10259-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to Continental Telecommunications System, Inc., hereunder referred to as the Grantee, its successors or assignees, under Republic Act No. 8579, to construct, install, maintain, establish, and operate for commercial purposes and in the public interest, in the Provinces of Batangas, Laguna and Masbate, wired or wireless telecommunications systems and facilities for domestic telecommunications, including local exchange network, public calling stations, pay telephone stations, or wireless local loop, using copper or fiber optics cables, switches, and satellite transmit and receive systems, and their value-added services such as transmission of voice, data, facsimile, control signs, audio and video, information services, and all other telecommunication systems and technologies as are at present available or will be made available through technological advances or innovations in the future; or construct, acquire, lease, and operate or manage transmitting and receiving stations, lines, cables, or systems, as are convenient or essential to efficiently carry out the purpose of this franchise, is hereby renewed for another twenty-five (25) years."}},{"id":"PH-H10259-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations or facilities of the Grantee shall be constructed and operated in a manner as will, at most, result only in the minimum interference on the wavelengths or frequencies of existing stations or other stations which may be established by law, without in any way diminishing its own privilege to use its assigned wavelengths or frequencies and the quality of transmission or reception thereon should maximize rendition of the Grantee's services and the availability thereof."}},{"id":"PH-H10259-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Authority of the National Telecommunications Commission. - The Grantee shall secure from the National Telecommunications Commission (NTC)a Certificate of Public Convenience and Necessity or the appropriate permits and licenses for the construction, installation, and operation of its telecommunications systems or facilities. In issuing the certificate, the NTC shall have the power to regulate and impose such conditions relative to the construction, operation, maintenance, or service level of the telecommunications systems or facilities. Such certificate shall state the areas covered and the date the Grantee shall commence the service. The Grantee shall not use any frequency in the radio spectrum without authorization from the NTC. The NTC, however, shall not unreasonably withhold or delay the grant of such authority, permit, or license.\nIn case of any violation of the provisions of this franchise, the NTC shall have the authority to revoke or suspend, after due process, the permits or licenses it issued pursuant to the franchise. The NTC may recommend to Congress of the Philippine the revocation of the franchise for any violation of the provisions of this franchise."}},{"id":"PH-H10259-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Excavation and Restoration Works. - For the purpose of erecting and maintaining poles or other supports for said wires or other conductors for the purpose of laying and maintaining underground wires, cables, or other conductors, it shall be lawful for the Grantee, its successors or assignees, with the prior approval of the Department of Public Works and Highways (DPWH) or the local government unit (LGU) concerned, as may be appropriate, to make excavations or lay conduits in any of the public places, roads, highways, streets, lanes, alleys, avenues, sidewalks, or bridges of the provinces, cities, or municipalities: Provided, however, That a public place, road, highway, street, lane, alley, sidewalk, or bridge disturbed, altered or changes by reason of erection of poles or other supports or the underground laying of wires, other conductors or conduits, shall be repaired and replaced in workmanlike manner by said Grantee, its successors or assignees, in accordance with the standards set by the DPWH or the LGU concerned. Should the Grantee, its successors or assignees, after ten (10)-day notice from the said authority, fail, refuse, or neglect to repair or replace any part of any public place, road, highway, street, lane, alley, avenue, sidewalk, bridge altered, changed or disturbed by the said Grantee, its successors or assignees, then the DPWH or the LGU concerned shall have the right to have the same repaired and placed in good order and condition, and charge the Grantee, its successors or assignees, at double the amount of the costs and expenses for such repair or replacement."}},{"id":"PH-H10259-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Responsibility to the Public. - The Grantee shall conform to the ethics of honest enterprise and not use its stations or facilities for obscene or indecent transmission, or for dissemination of deliberately false information, or willful misrepresentation, or assist in subversive or treasonable acts.\nThe Grantee shall operate and maintain all its stations, lines, cables, systems, and equipment for the transmission and reception of messages, signals, and pulses in a satisfactory manner at all times, and as far as economical and practicable, modify, improve, or change such stations, lines, cables, systems, and equipment to keep abreast with the advances in science and technology.\nThe Grantee shall improve and extend its services in areas not yet served, and in hazard- and typhoon-prone areas that shall be determined by the National Disaster Risk Reduction and Management Council, or its legal successor, in coordination with the NTC.\nThe Grantee shall also improve and upgrade its equipment, facilities and services, in order to ensure effective compliance with the objectives of Republic Act No. 10639 or \"The Free Mobile Disaster Alerts Act.\""}},{"id":"PH-H10259-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Rates for Services. - The charges and rates for telecommunications services of the Grantee, except the rates and charges on those that may hereafter be declared or considered as nonregulated services, whether flat rates or measured rates or variations thereof, shall be subject to the approval of the NTC or its legal successor. The rates to be charged by the Grantee shall be unbundled, separable, and distinct among the services offered and shall be determined in such a manner that regulated services do not subsidize the unregulated ones."}},{"id":"PH-H10259-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Right of the Government. - The radio spectrum is a finite resource that is part of the national patrimony, and the use thereof is a privilege conferred upon the Grantee by the State that may be withdrawn any time after due process.\nA special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster, or disturbance of peace and order: to temporarily take over and operate the stations, transmitters, facilities or equipment of the Grantee; to temporarily suspend the operation of any station, transmitter, facility, or equipment in the interest of public safety, security, and public welfare; or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the Grantee for the use of said stations, transmitters, facilities, or equipment during the period when these shall be so operated."}},{"id":"PH-H10259-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Term of Franchise. - This franchise shall be in effect for a period of twenty-five (25) years from the effectivity of this Act, unless sooner revoked or cancelled. This franchise shall be deemed ipso facto revoked in the event the Grantee fails to operate continuously for two (2) years."}},{"id":"PH-H10259-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Right of Interconnection. - The Grantee is hereby authorized to connect or demand connection of its telecommunications systems to other telecommunications systems installed, operated, and maintained by any other duly authorized person or entity in the Philippines for the purpose of providing extended and improved telecommunications services to the public, under the terms and conditions mutually agreed upon by the parties concerned. This right shall be subject to the review and modification of the NTC."}},{"id":"PH-H10259-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of the National and Local Governments. - The Grantee shall hold the national, provincial, city, and municipal governments of the Philippines free from all claims, liabilities, accounts, demands, or actions arising out of accidents causing injury to persons or damage to properties, during the construction or operation of the stations, transmitters, facilities, or equipment of the Grantee."}},{"id":"PH-H10259-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sales, Lease, Transfer, Grant of Usufruct, or Assignment of Franchise. - The Grantee shall not sell, lease, transfer, grant of usufruct of, nor assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any corporation or entity, nor shall the controlling interest of the Grantee be transferred, simultaneously or contemporaneously, to any person, firm, company, corporation, or entity without the prior approval of Congress. The Grantee shall inform the Congress, through the Office of the Speaker and Office of the Senate President, of any sale, lease, transfer, grant of usufruct, or assignment of franchise or the rights and privileges acquired thereunder, or of the merger or transfer of the controlling interest of the Grantee, within sixty (60) days after the completion of the said transaction. Failure to report to Congress such change of ownership shall render the franchise ipso facto revoked. Any person or entity to which this franchise is sold, transferred, or assigned shall be subject to the same conditions, terms, restrictions, and limitations of this Act."}},{"id":"PH-H10259-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Dispersal of Ownership. - In accordance with the constitutional provision to encourage public participation in public utilities, the Grantee shall offer to Filipino citizens at least thirty percent (30%) of its outstanding capital stocks, or a higher percentage that may hereafter be provided by law, in any securities exchange in the Philippines within five (5) years from the effectivity of this Act: Provided, That in cases where public offer of shares is not applicable, other methods of encouraging public participation by citizens and corporations operating public utilities must be implemented. Noncompliance therewith shall render the franchise ipso facto revoked."}},{"id":"PH-H10259-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Commitment to Provide and Promote the Creation of Employment Opportunities. - The Grantee shall create employment opportunities and accept on-the-job trainees in the franchise operations: Provided, That priority shall be accorded to the residents of the place where the principal office of the Grantee is located: Provided, further, That the Grantee shall comply with the applicable labor standards and allowance entitlement under existing labor laws, rules and regulations and similar issuances.\nThe employment opportunities or jobs created shall be reflected in the General Information Sheet (GIS) to be submitted to Securities and Exchange Commission (SEC) annually."}},{"id":"PH-H10259-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Reportorial Requirement. - The Grantee shall submit an annual report on its compliance with the terms and conditions of the franchise and on its operations to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate, on or before April 30 of every year during the term of its franchise.\nThe annual report shall include an update on the commencement of activities, development, operation or expansion of business; audited financial statements; latest GIS officially submitted to the SEC, if applicable; certification of the NTC on the status of its permits and operations; and an update on the dispersal of ownership undertaking, if applicable.\nThe reportorial compliance certificate issued by Congress shall required before any application for permit or certificate is accepted by the NTC."}},{"id":"PH-H10259-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Fine. - Failure of the Grantee to submit the requisite annual report to Congress shall be penalized with a fine in the amount of One million pesos (P1,000,000.00) each working day of noncompliance, the effectivity of which shall commence upon applicability with other telecommunications franchise grantees: Provided, That in the interim, the Grantee shall be liable to pay the fine of Five hundred pesos (P500.00) per working day of noncompliance to the NTC. The fine shall be collected separately from the reportorial penalties imposed by the NTC, and it shall be remitted to the Bureau of Treasury."}},{"id":"PH-H10259-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Equality of Treatment in the Telecommunications Industry. - Any advantage, favor, privilege, exemption or immunity granted under existing franchises, or which may hereafter be granted for telecommunications, upon prior review and approval of Congress, shall become part of this franchise and shall be accorded immediately and unconditionally to the herein Grantee: Provided, however, That the foregoing shall neither apply to nor affect the provisions of telecommunications franchises concerning territorial covered by the franchise, the life span of the franchise, or the type of service authorized by the franchise."}},{"id":"PH-H10259-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Repealability and Nonexclusivity Clause. - This franchise shall be subject to amendment, alteration, or repeal by Congress when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H10259-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Separability Clause. - If any of the sections or provisions of this Act is held invalid, all other provisions not affected thereby shall remain valid."}},{"id":"PH-H10259-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Repealing Clause. - All laws, decrees, orders, resolutions, instructions, rules and regulations, and other issuances or parts thereof which are inconsistent with the provisions of this Act are hereby repealed, amended, or modified accordingly."}},{"id":"PH-H10259-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p146","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Renewing for Another Twenty-Five (25) Years the Franchise Granted to Continental Telecommunications System Inc., Under the Republic Act No. 8579, Entitled \"an Act Granting the Continental Telecommunications System, Inc., a Franchise to Construct, Install, Maintain, Establish and Operate Local Exchange Network in the Provinces of Batangas, Laguna, and Masbate\"","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H10260"] = {"id":"PH-H10260","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11832_2022.html","fetchedAt":"2026-10-06","articleCount":17,"structureMode":"ARTICLE","title":{"zh":"授予 South Cotabato 通信公司在南哥打巴托省境内建设、安装、设立、运营和维护广播电视站的特许经营权法案","en":"An Act Granting South Cotabato Communications Corporation a Franchise to Construct, Install, Establish, Operate, and Maintain Radio and Televisions Broadcasting Stations Within the Province of South Cotabato","orig":"An Act Granting South Cotabato Communications Corporation a Franchise to Construct, Install, Establish, Operate, and Maintain Radio and Televisions Broadcasting Stations Within the Province of South Cotabato"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 11832","issuingBody":"Congress of the Philippines","promulgatedDate":"2022-06-02","completenessNote":"全文，共 17 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2022/ra_11832_2022.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10260-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to South Cotabato Communications Corporation, hereunder referred to as the Grantee, its successors or assignees, a franchise to construct, install, establish, operate and maintain for religious, educational, cultural, and commercial purposes and in the public interest, radio and television broadcasting station within the Province of South Cotabato where frequencies and channels are still available for radio and television broadcasting, including digital television system, through microwave, satellite or whatever means, as well as the use of any technology in radio and television systems, with the corresponding technological auxiliaries or facilities, special broadcast and other program and distribution services and relay stations."}},{"id":"PH-H10260-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations or facilities of the Grantee shall be constructed and operated in a manner as will, at most, result only in the minimum interference on the wavelengths or frequencies of existing stations or other stations which may be established by law, without in any way diminishing its own privilege to use its assigned wavelengths or frequencies and the quality of transmission or reception thereon should maximize rendition of the Grantee's services and the availability thereof."}},{"id":"PH-H10260-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. - The Grantee shall secure from the National Telecommunications Commission (NTC) the appropriate permits and licenses for the construction and operation of its stations or facilities and shall not use any frequency in the radio spectrum without the authorization from the NTC. The NTC, however, shall not unreasonably withhold or delay the grant of any such authority.\nIn case of any violation of the provisions of this franchise, the NTC shall have the authority to revoke or suspend, after due process, the permits or licenses it issued pursuant to the franchise. The NTC may recommend to Congress of the Philippine the revocation of the franchise for any violation of the provisions of this franchise."}},{"id":"PH-H10260-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. - The Grantee shall provide free of charge, adequate public service time which is reasonable and sufficient to enable the government, through the broadcasting stations and facilities of the Grantee, to react the pertinent populations or portions thereof, on important public issues and relay important public announcements and warnings concerning public emergencies and calamities, as necessity, urgency, or law may require; provide at all times sound and balanced programming; promote public participation; assist in the functions of public information and education; conform to the ethics of honest enterprise; promote audience sensibility and empowerment including closed captioning; and not use its stations or facilities for the broadcasting of obscene or indecent language, speech, act or scene, the dissemination of deliberately false information or willful misrepresentation, to the detriment of public interest, or to incite, encourage, or assist in subversive or treasonable acts.\nPublic service time referred herein shall be equivalent to a maximum aggregate of ten percent (10%) of paid commercials or advertisements which shall be allocated based on the need to the Executive and Legislative branches, the Judiciary, Constitutional Commissions, and international humanitarian organizations duly recognized by statutes: Provided, That the NTC shall increase the public service time in case of extreme emergency or calamity. The NTC shall issue the rules and regulations for this purpose, the effectivity of which shall commence upon applicability with other similarly situated broadcast network franchise holders.\nPursuant to Republic Act No. 8370, otherwise known as the “Children’s Television Act of 1997”, the Grantee shall allot a minimum of fifteen percent (15%) of the daily total air time of each broadcasting network or station to child-friendly shows within its regular programming."}},{"id":"PH-H10260-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of the Government. - The radio spectrum is a finite resource that is part of the national patrimony, and the use thereof is a privilege conferred upon the Grantee by the State that may be withdrawn any time after due process.\nA special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster, or disturbance of peace and order: to temporarily take over and operate the stations, transmitters, facilities or equipment of the Grantee; to temporarily suspend the operation of any station, transmitter, facility, or equipment in the interest of public safety, security, and public welfare; or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the Grantee for the use of said stations, transmitters, facilities, or equipment during the period when these shall be so operated."}},{"id":"PH-H10260-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. - This franchise shall be in effect for a period of twenty-five (25) years from the effectivity of this Act, unless sooner revoked or cancelled. This franchise shall be deemed ipso facto revoked in the event the Grantee fails to operate continuously for two (2) years."}},{"id":"PH-H10260-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Self-regulation by and Undertaking of the Grantee. - The Grantee shall not require any previous censorship of any speech, play, act or scene, or other matter to be broadcast from its stations, but if any such speech, play, act or scene, or other matter should constitute a violation of the law or infringement of a private right, the Grantee shall be free from any liability, civil or criminal, for such speech, play, act or scene, or other matter: Provided, That the Grantee, during any broadcast, shall cut off the airing of speech, play, act or scene, or other matter being broadcast if the tendency thereof is to propose or incite treason, rebellion, or sedition; or the language used therein or the theme thereof is indecent or immoral: Provided, further, That willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H10260-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Warranty in Favor of the National and Local Governments. - The Grantee shall hold the national, provincial, city, and municipal governments of the Philippines free from all claims, liabilities, accounts, demands, or actions arising out of accidents causing injury to persons or damage to properties, during the construction or operation of the stations, transmitters, facilities, or equipment of the Grantee."}},{"id":"PH-H10260-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Commitment to Provide and Promote the Creation of Employment Opportunities. - The Grantee shall create employment opportunities and accept on-the-job trainees in the franchise operations: Provided, That priority shall be accorded to the residents of the place where the principal office of the Grantee is located: Provided, further, That the Grantee shall comply with the applicable labor standards and allowance entitlement under existing labor laws, rules and regulations and similar issuances.\nThe employment opportunities or jobs created shall be reflected in the General Information Sheet (GIS) to be submitted to Securities and Exchange Commission (SEC) annually."}},{"id":"PH-H10260-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Sales, Lease, Transfer, Grant of Usufruct, or Assignment of Franchise. - The Grantee shall not sell, lease, transfer, grant of usufruct of, nor assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any corporation or entity, nor shall the controlling interest of the Grantee be transferred, simultaneously or contemporaneously, to any person, firm, company, corporation, or entity without the prior approval of Congress. The Grantee shall inform the Congress, through the Office of the Speaker and Office of the Senate President, of any sale, lease, transfer, grant of usufruct, or assignment of franchise or the rights and privileges acquired thereunder, or of the merger or transfer of the controlling interest of the Grantee, within sixty (60) days after the completion of the said transaction. Failure to report to Congress such change of ownership shall render the franchise ipso facto revoked. Any person or entity to which this franchise is sold, transferred, or assigned shall be subject to the same conditions, terms, restrictions, and limitations of this Act."}},{"id":"PH-H10260-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Reportorial Requirement. - The Grantee shall submit an annual report on its compliance with the terms and conditions of the franchise and on its operations to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate, on or before April 30 of every year during the term of its franchise.\nThe annual report shall include an update on the commencement of activities, development, operation or expansion of business; audited financial statements; latest GIS officially submitted to the SEC, if applicable; certification of the NTC on the status of its permits and operations; and an update on the dispersal of ownership undertaking, if applicable.\nThe reportorial compliance certificate issued by Congress shall required before any application for permit or certificate is accepted by the NTC."}},{"id":"PH-H10260-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Fine. - Failure of the Grantee to submit the requisite annual report to Congress shall be penalized with a fine of Five hundred pesos (P500.00) per working day of noncompliance to the NTC. The fine shall be collected separately from the reportorial penalties imposed by the NTC, and it shall be remitted to the Bureau of Treasury"}},{"id":"PH-H10260-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Equality Clause. – Any advantage, favor, privilege, exemption, or immunity granted under existing franchises, or which may hereafter be granted for radio and television broadcasting, upon prior review and approval of Congress, shall become part of this franchise and shall be accorded immediately and unconditionally to the herein Grantee: Provided, That the foregoing shall neither apply to nor affect the provisions of broadcasting franchises concerning territorial coverage, the term, or the type of service authorized by the franchise."}},{"id":"PH-H10260-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Repealability and Nonexclusivity Clause. - This franchise shall be subject to amendment, alteration, or repeal by Congress when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H10260-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Separability Clause. - If any of the sections or provisions of this Act is held invalid, all other provisions not affected thereby shall remain valid."}},{"id":"PH-H10260-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Repealing Clause. - All laws, decrees, orders, resolutions, instructions, rules and regulations, and other issuances or parts thereof which are inconsistent with the provisions of this Act are hereby repealed, amended, or modified accordingly."}},{"id":"PH-H10260-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation"}}],"pack":"ph-p146","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting South Cotabato Communications Corporation a Franchise to Construct, Install, Establish, Operate, and Maintain Radio and Televisions Broadcasting Stations Within the Province of South Cotabato","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H10261"] = {"id":"PH-H10261","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11833_2022.html","fetchedAt":"2026-10-06","articleCount":18,"structureMode":"ARTICLE","title":{"zh":"授予 Prime 广播网络公司在菲律宾建设、安装、设立、运营和维护广播电视站的特许经营权法案","en":"An Act Granting Prime Broadcasting Network, Inc. a Franchise to Construct, Install, Establish, Operate, and Maintain Radio and Television Broadcasting Stations in the Philippines","orig":"An Act Granting Prime Broadcasting Network, Inc. a Franchise to Construct, Install, Establish, Operate, and Maintain Radio and Television Broadcasting Stations in the Philippines"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 11833","issuingBody":"Congress of the Philippines","promulgatedDate":"2022-06-02","completenessNote":"全文，共 18 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2022/ra_11833_2022.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10261-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to Prime Broadcasting Network, Inc., hereunder referred to as the Grantee, its successors or assignees, a franchise to construct, install, establish, operate and maintain for commercial purposes and in the public interest, radio and television broadcasting station in the Philippines, where frequencies and channels are still available for radio and television broadcasting, including digital television system, through microwave, satellite or whatever means, as well as the use of any technology in radio and television systems, with the corresponding technological auxiliaries or facilities, special broadcast and other program and distribution services and relay stations."}},{"id":"PH-H10261-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations or facilities of the Grantee shall be constructed and operated in a manner as will, at most, result only in the minimum interference on the wavelengths or frequencies of existing stations or other stations which may be established by law, without in any way diminishing its own privilege to use its assigned wavelengths or frequencies and the quality of transmission or reception thereon should maximize rendition of the Grantee's services and the availability thereof."}},{"id":"PH-H10261-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. - The Grantee shall secure from the National Telecommunications Commission (NTC) the appropriate permits and licenses for the construction and operation of its stations or facilities and shall not use any frequency in the radio spectrum without the authorization from the NTC. The NTC, however, shall not unreasonably withhold or delay the grant of any such authority.\nIn case of any violation of the provisions of this franchise, the NTC shall have the authority to revoke or suspend, after due process, the permits or licenses it issued pursuant to the franchise. The NTC may recommend to Congress of the Philippine the revocation of the franchise for any violation of the provisions of this franchise."}},{"id":"PH-H10261-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. - The Grantee shall provide free of charge, adequate public service time which is reasonable and sufficient to enable the government, through the broadcasting stations and facilities of the Grantee, to react the pertinent populations or portions thereof, on important public issues and relay important public announcements and warnings concerning public emergencies and calamities, as necessity, urgency, or law may require; provide at all times sound and balanced programming; promote public participation; assist in the functions of public information and education; conform to the ethics of honest enterprise; promote audience sensibility and empowerment including closed captioning; and not use its stations or facilities for the broadcasting of obscene or indecent language, speech, act or scene, the dissemination of deliberately false information or willful misrepresentation, to the detriment of public interest, or to incite, encourage, or assist in subversive or treasonable acts.\nPublic service time referred herein shall be equivalent to a maximum aggregate of ten percent (10%) of paid commercials or advertisements which shall be allocated based on the need to the Executive and Legislative branches, the Judiciary, Constitutional Commissions, and international humanitarian organizations duly recognized by statutes: Provided, That the NTC shall increase the public service time in case of extreme emergency or calamity. The NTC shall issue the rules and regulations for this purpose, the effectivity of which shall commence upon applicability with other similarly situated broadcast network franchise holders.\nPursuant to Republic Act No. 8370, otherwise known as the “Children’s Television Act of 1997”, the Grantee shall allot a minimum of fifteen percent (15%) of the daily total air time of each broadcasting network or station to child-friendly shows within its regular programming."}},{"id":"PH-H10261-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of the Government. - The radio spectrum is a finite resource that is part of the national patrimony, and the use thereof is a privilege conferred upon the Grantee by the State that may be withdrawn any time after due process.\nA special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster, or disturbance of peace and order: to temporarily take over and operate the stations, transmitters, facilities or equipment of the Grantee; to temporarily suspend the operation of any station, transmitter, facility, or equipment in the interest of public safety, security, and public welfare; or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the Grantee for the use of said stations, transmitters, facilities, or equipment during the period when these shall be so operated."}},{"id":"PH-H10261-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. - This franchise shall be in effect for a period of twenty-five (25) years from the effectivity of this Act, unless sooner revoked or cancelled. This franchise shall be deemed ipso facto revoked in the event the Grantee fails to operate continuously for two (2) years."}},{"id":"PH-H10261-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Self-regulation by and Undertaking of the Grantee. - The Grantee shall not require any previous censorship of any speech, play, act or scene, or other matter to be broadcast from its stations, but if any such speech, play, act or scene, or other matter should constitute a violation of the law or infringement of a private right, the Grantee shall be free from any liability, civil or criminal, for such speech, play, act or scene, or other matter: Provided, That the Grantee, during any broadcast, shall cut off the airing of speech, play, act or scene, or other matter being broadcast if the tendency thereof is to propose or incite treason, rebellion, or sedition; or the language used therein or the theme thereof is indecent or immoral: Provided, further, That willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H10261-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Warranty in Favor of the National and Local Governments. - The Grantee shall hold the national, provincial, city, and municipal governments of the Philippines free from all claims, liabilities, accounts, demands, or actions arising out of accidents causing injury to persons or damage to properties, during the construction or operation of the stations, transmitters, facilities, or equipment of the Grantee."}},{"id":"PH-H10261-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Commitment to Provide and Promote the Creation of Employment Opportunities. - The Grantee shall create employment opportunities and accept on-the-job trainees in the franchise operations: Provided, That priority shall be accorded to the residents of the place where the principal office of the Grantee is located: Provided, further, That the Grantee shall comply with the applicable labor standards and allowance entitlement under existing labor laws, rules and regulations and similar issuances.\nThe employment opportunities or jobs created shall be reflected in the General Information Sheet (GIS) to be submitted to Securities and Exchange Commission (SEC) annually."}},{"id":"PH-H10261-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Sales, Lease, Transfer, Grant of Usufruct, or Assignment of Franchise. - The Grantee shall not sell, lease, transfer, grant of usufruct of, nor assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any corporation or entity, nor shall the controlling interest of the Grantee be transferred, simultaneously or contemporaneously, to any person, firm, company, corporation, or entity without the prior approval of Congress. The Grantee shall inform the Congress, through the Office of the Speaker and Office of the Senate President, of any sale, lease, transfer, grant of usufruct, or assignment of franchise or the rights and privileges acquired thereunder, or of the merger or transfer of the controlling interest of the Grantee, within sixty (60) days after the completion of the said transaction. Failure to report to Congress such change of ownership shall render the franchise ipso facto revoked. Any person or entity to which this franchise is sold, transferred, or assigned shall be subject to the same conditions, terms, restrictions, and limitations of this Act."}},{"id":"PH-H10261-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Dispersal of Ownership. – In accordance with the constitutional provision to encourage public participation in public utilities, the Grantee shall offer to Filipino citizens at least thirty percent (30%) of its outstanding capital stock, or a higher percentage that may hereafter be provided by law, in any securities exchange in the Philippines within five (5) years from the effectivity of this Act: Provided, That in cases where public offer of shares is not applicable, other methods of encouraging public participation by citizens and corporations operating public utilities must be implemented. Noncompliance therewith shall render the franchise ipso facto revoked."}},{"id":"PH-H10261-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Reportorial Requirement. - The Grantee shall submit an annual report on its compliance with the terms and conditions of the franchise and on its operations to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate, on or before April 30 of every year during the term of its franchise.\nThe annual report shall include an update on the commencement of activities, development, operation or expansion of business; audited financial statements; latest GIS officially submitted to the SEC, if applicable; certification of the NTC on the status of its permits and operations; and an update on the dispersal of ownership undertaking, if applicable.\nThe reportorial compliance certificate issued by Congress shall required before any application for permit or certificate is accepted by the NTC."}},{"id":"PH-H10261-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Fine. - Failure of the Grantee to submit the requisite annual report to Congress shall be penalized with a fine of Five hundred pesos (P500.00) per working day of noncompliance to the NTC. The fine shall be collected separately from the reportorial penalties imposed by the NTC, and it shall be remitted to the Bureau of Treasury"}},{"id":"PH-H10261-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Equality Clause. – Any advantage, favor, privilege, exemption, or immunity granted under existing franchises, or which may hereafter be granted for radio and television broadcasting, upon prior review and approval of Congress, shall become part of this franchise and shall be accorded immediately and unconditionally to the herein Grantee: Provided, That the foregoing shall neither apply to nor affect the provisions of broadcasting franchises concerning territorial coverage, the term, or the type of service authorized by the franchise."}},{"id":"PH-H10261-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Repealability and Nonexclusivity Clause. - This franchise shall be subject to amendment, alteration, or repeal by Congress when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H10261-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Separability Clause. - If any of the sections or provisions of this Act is held invalid, all other provisions not affected thereby shall remain valid."}},{"id":"PH-H10261-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Repealing Clause. - All laws, decrees, orders, resolutions, instructions, rules and regulations, and other issuances or parts thereof which are inconsistent with the provisions of this Act are hereby repealed, amended, or modified accordingly."}},{"id":"PH-H10261-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation"}}],"pack":"ph-p146","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Prime Broadcasting Network, Inc. a Franchise to Construct, Install, Establish, Operate, and Maintain Radio and Television Broadcasting Stations in the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
